-- Conventions for every table (docs/backend/modelo-de-dados.md):
--   id uuid (v7, generated by the application), owner_id uuid (RNF-SEG-03),
--   created_at / updated_at timestamptz, version bigint (optimistic locking),
--   enums as text + CHECK in upper case, money as numeric(14,2) in BRL.
-- One schema per module. Foreign keys only inside a module; references to another
-- module are plain uuid columns checked by the application (ADR-003).

-- Spring Modulith event publication registry (v2 schema of spring-modulith-events-jdbc).
CREATE TABLE event_publication
(
  id                     UUID NOT NULL,
  listener_id            TEXT NOT NULL,
  event_type             TEXT NOT NULL,
  serialized_event       TEXT NOT NULL,
  publication_date       TIMESTAMP WITH TIME ZONE NOT NULL,
  completion_date        TIMESTAMP WITH TIME ZONE,
  status                 TEXT,
  completion_attempts    INT,
  last_resubmission_date TIMESTAMP WITH TIME ZONE,
  PRIMARY KEY (id)
);
CREATE INDEX event_publication_serialized_event_hash_idx ON event_publication USING hash(serialized_event);
CREATE INDEX event_publication_by_completion_date_idx ON event_publication (completion_date);

CREATE SCHEMA identity;

CREATE TABLE identity.app_user
(
  id         uuid PRIMARY KEY,
  name       varchar(120) NOT NULL,
  email      varchar(254) NOT NULL UNIQUE,
  locale     varchar(10)  NOT NULL DEFAULT 'pt-BR',
  time_zone  varchar(40)  NOT NULL DEFAULT 'America/Sao_Paulo',
  created_at timestamptz  NOT NULL DEFAULT now(),
  updated_at timestamptz  NOT NULL DEFAULT now(),
  version    bigint       NOT NULL DEFAULT 0
);
